    const daysSinceLastUpdate = Math.floor(
      (new Date(timestamp).getTime() - lastUpdateDate.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    const requiresImmediateReflection = daysSinceLastUpdate >= 7 || detectedChanges.length > 0;
  
