/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndPrioritizeRestrictionChanges exports=detectAndPrioritizeRestrictionChanges */
const __aivicBundle_6_detectAndPrioritizeRestrictionChanges = (() => {
  function detectAndPrioritizeRestrictionChanges(input: {
    userProfile: {
      userId: string;
      familyMembers: Array<{
        memberId: string;
        name: string;
        age: number;
        restrictions?: Array<{
          restrictionId: string;
          type: string;
          lastUpdatedAt: Date;
        }>;
        allergies?: Array<{
          allergyId: string;
          ingredient: string;
          severity: string;
          lastUpdatedAt: Date;
        }>;
      }>;
    };
    currentDate: Date;
    thresholdDays: number;
  }): {
    detectedChanges: Array<{
      lastUpdatedAt: Date;
      memberId: string;
      type: string;
      priority: string;
    }>;
    summary: {
      totalDetected: number;
      highPriorityCount: number;
      mediumPriorityCount: number;
      lowPriorityCount: number;
    };
  } {
    const detectedChanges: Array<{
      lastUpdatedAt: Date;
      memberId: string;
      type: string;
      priority: string;
    }> = [];
  
    const calculateDaysOld = (current: Date, lastUpdated: Date): number => {
      const diffMs = current.getTime() - lastUpdated.getTime();
      return Math.floor(diffMs / (1000 * 60 * 60 * 24));
    };
  
    const determinePriority = (daysOld: number): string => {
      if (daysOld >= 7) {
        return "HIGH";
      } else if (daysOld >= 3) {
        return "MEDIUM";
      } else {
        return "LOW";
      }
    };
  
    for (const member of input.userProfile.familyMembers) {
      if (member.restrictions) {
        for (const restriction of member.restrictions) {
          const daysOld = calculateDaysOld(
            input.currentDate,
            restriction.lastUpdatedAt
          );
          const priority = determinePriority(daysOld);
  
          detectedChanges.push({
            lastUpdatedAt: restriction.lastUpdatedAt,
            memberId: member.memberId,
            type: "restriction",
            priority,
          });
        }
      }
  
      if (member.allergies) {
        for (const allergy of member.allergies) {
          const daysOld = calculateDaysOld(
            input.currentDate,
            allergy.lastUpdatedAt
          );
          const priority = determinePriority(daysOld);
  
          detectedChanges.push({
            lastUpdatedAt: allergy.lastUpdatedAt,
            memberId: member.memberId,
            type: "allergy",
            priority,
          });
        }
      }
    }
  
    const highPriorityCount = detectedChanges.filter(
      (item) => item.priority === "HIGH"
    ).length;
    const mediumPriorityCount = detectedChanges.filter(
      (item) => item.priority === "MEDIUM"
    ).length;
    const lowPriorityCount = detectedChanges.filter(
      (item) => item.priority === "LOW"
    ).length;
  
    return {
      detectedChanges,
      summary: {
        totalDetected: detectedChanges.length,
        highPriorityCount,
        mediumPriorityCount,
        lowPriorityCount,
      },
    };
  }
  return { detectAndPrioritizeRestrictionChanges };
})();
export const detectAndPrioritizeRestrictionChanges = __aivicBundle_6_detectAndPrioritizeRestrictionChanges.detectAndPrioritizeRestrictionChanges;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAndPrioritizeRestrictionChanges */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndPrioritizeConstraintChanges exports=detectAndPrioritizeConstraintChanges */
const __aivicBundle_7_detectAndPrioritizeConstraintChanges = (() => {
  function detectAndPrioritizeConstraintChanges(
    constraintRecords: Array<{
      constraint_id: string;
      user_id: string;
      restriction_type: string;
      restriction_name: string;
      last_updated_at: Date;
      priority_category: string | null;
    }>,
    currentMockTime: Date,
    thresholdDays: number
  ): {
    prioritized_constraints: Array<{
      constraint_id: string;
      priority_category: string;
    }>;
    total_records: number;
    prioritized_count: number;
    excluded_count: number;
    constraint_change_log: Array<{
      constraint_id: string;
      action: string;
      reason: string;
      elapsed_days: number;
    }>;
    warning_logged: boolean;
  } {
    const prioritized_constraints: Array<{
      constraint_id: string;
      priority_category: string;
    }> = [];
    const constraint_change_log: Array<{
      constraint_id: string;
      action: string;
      reason: string;
      elapsed_days: number;
    }> = [];
  
    let prioritized_count = 0;
    let excluded_count = 0;
  
    for (const record of constraintRecords) {
      const elapsedMillis =
        currentMockTime.getTime() - record.last_updated_at.getTime();
      const elapsedDays = elapsedMillis / (1000 * 60 * 60 * 24);
  
      if (elapsedDays >= thresholdDays) {
        prioritized_constraints.push({
          constraint_id: record.constraint_id,
          priority_category: "HIGH",
        });
        constraint_change_log.push({
          constraint_id: record.constraint_id,
          action: "prioritized",
          reason: `${thresholdDays}日以上経過`,
          elapsed_days: Math.round(elapsedDays),
        });
        prioritized_count++;
      } else {
        constraint_change_log.push({
          constraint_id: record.constraint_id,
          action: "excluded_below_threshold",
          reason: `${thresholdDays}日未満の経過`,
          elapsed_days: parseFloat(elapsedDays.toFixed(2)),
        });
        excluded_count++;
      }
    }
  
    return {
      prioritized_constraints,
      total_records: constraintRecords.length,
      prioritized_count,
      excluded_count,
      constraint_change_log,
      warning_logged: false,
    };
  }
  return { detectAndPrioritizeConstraintChanges };
})();
export const detectAndPrioritizeConstraintChanges = __aivicBundle_7_detectAndPrioritizeConstraintChanges.detectAndPrioritizeConstraintChanges;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAndPrioritizeConstraintChanges */

