const __aivicBundle_8_normalizeAndValidateRefrigeratorInventory = (() => {
  function normalizeAndValidateRefrigeratorInventory(input: {
    ingredient_name: string;
    quantity: number;
    unit: string;
    expiration_date?: string;
  }): InventoryValidationResult {
    const validation_errors: string[] = [];
  
    // 食材名の検証
    if (!input.ingredient_name || input.ingredient_name.trim() === '') {
      throw new Error('食材名は必須です');
    }
  
    const normalized_ingredient_name = input.ingredient_name.trim();
  
    // 数量と単位の正規化
    const normalized_quantity_with_unit = `${input.quantity}${input.unit}`;
  
    // 賞味期限の正規化（存在する場合）
    const normalized_expiration_date = input.expiration_date || '';
  
    // バリデーション結果の判定
    const is_valid = validation_errors.length === 0;
  
    // 制約条件への反映ステータス
    const constraint_reflection_status = is_valid ? 'ready_for_generation' : 'validation_failed';
  
    return {
      normalized_ingredient_name,
      normalized_quantity_with_unit,
      normalized_expiration_date,
      is_valid,
      validation_errors,
      constraint_reflection_status,
    };
  }
  return { normalizeAndValidateRefrigeratorInventory };
})();
