/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndNormalizeInventory exports=validateAndNormalizeInventory */
const __aivicBundle_9_validateAndNormalizeInventory = (() => {
  function validateAndNormalizeInventory(
    input: {
      itemName?: string;
      foodName?: string;
      quantity?: number;
      quantityUnit?: string;
      expirationDate?: string;
      expiryDate?: string;
      storageLocation?: string;
    },
    today: Date
  ): any {
    const itemName = (input.itemName || input.foodName || "").trim();
    const quantity = input.quantity ?? 0;
    const quantityUnit = input.quantityUnit || "";
    const expirationDateStr = input.expirationDate || input.expiryDate || "";
    const storageLocation = input.storageLocation || "";
  
    const errors: string[] = [];
  
    if (!itemName) {
      errors.push("食材名は必須です");
    }
  
    if (quantity <= 0) {
      errors.push("数量は0より大きい値である必要があります");
    }
  
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(expirationDateStr)) {
      errors.push("賞味期限のフォーマットが不正です（YYYY-MM-DD形式で指定してください）");
    }
  
    if (errors.length > 0) {
      throw new Error(errors.join(", "));
    }
  
    const expiryDate = new Date(expirationDateStr + "T00:00:00Z");
    const todayNormalized = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    const expiryDateNormalized = new Date(expiryDate.getFullYear(), expiryDate.getMonth(), expiryDate.getDate());
  
    if (expiryDateNormalized < todayNormalized) {
      throw new Error("賞味期限切れの食材は使用できません");
    }
  
    const normalizedItemName = itemName;
    const isValid = true;
  
    let expiryDateStatus: string | undefined;
    if (expiryDateNormalized.getTime() === todayNormalized.getTime()) {
      expiryDateStatus = "available_today";
    }
  
    const canUseOnDate = (date: Date): boolean => {
      const dateNormalized = new Date(date.getFullYear(), date.getMonth(), date.getDate());
      return dateNormalized <= expiryDateNormalized;
    };
  
    const constraintAppliedDate = expirationDateStr;
    const nextDay = new Date(expiryDateNormalized);
    nextDay.setDate(nextDay.getDate() + 1);
    const excludeFoodsFromDate = nextDay.getFullYear() + "-" +
      String(nextDay.getMonth() + 1).padStart(2, "0") + "-" +
      String(nextDay.getDate()).padStart(2, "0");
  
    const mealPlanConstraints = {
      availableFoods: [normalizedItemName],
      constraintAppliedDate,
      excludeFoodsFromDate,
    };
  
    if (input.foodName !== undefined) {
      return {
        errors: [],
        isValid: true,
        normalized: {
          foodName: normalizedItemName,
          quantity,
          quantityUnit,
          expiryDate: expiryDate,
          storageLocation,
        },
        expiryDateStatus,
        canUseOnDate,
        mealPlanConstraints,
      };
    }
  
    return {
      itemName,
      quantity,
      quantityUnit,
      expirationDate: expirationDateStr,
      isValid,
      normalizedItemName,
    };
  }
  return { validateAndNormalizeInventory };
})();
