const __aivicBundle_13_generateMultiConstraintMeals = (() => {
  function generateMultiConstraintMeals(input: {
    constraints: MealConstraints;
    familyMembers?: Array<{
      memberId?: string;
      age?: number;
      allergies?: string[];
    }>;
    priorityOrder?: { [key: string]: number };
    candidateMenus?: MealCandidate[];
  }): RankedMealResult & { mealCandidates?: Array<{
    id: string;
    name: string;
    totalCalories: number;
    cookingTimeMinutes: number;
    budget: number;
    ingredients: string[];
    allergyRisks: string[];
    satisfactionScore: number;
    priorityLevel: number;
  }> } {
    const { constraints, familyMembers = [], priorityOrder = {}, candidateMenus = [] } = input;
  
    const calorieLimit = constraints.calorieLimit || constraints.calorieUpperLimit || Infinity;
    const cookingTimeLimit = constraints.cookingTimeLimit || constraints.cookingTimeUpperLimitMinutes || Infinity;
    const allergyExclusions = constraints.allergyExclusions || constraints.excludeAllergens || [];
    const budgetLimit = constraints.budgetLimit || Infinity;
  
    const allFamilyAllergies = new Set<string>();
    familyMembers.forEach((member) => {
      (member.allergies || []).forEach((allergy) => {
        allFamilyAllergies.add(allergy);
      });
    });
  
    const combinedAllergyExclusions = new Set<string>([
      ...allergyExclusions,
      ...allFamilyAllergies,
    ]);
  
    const rankedCandidates: Array<{
      id: string;
      name: string;
      calories: number;
      cookingTime: number;
      budget: number;
      allergyRisks: string[];
      satisfactionScore: number;
      totalCalories?: number;
      cookingTimeMinutes?: number;
      ingredients?: string[];
      priorityLevel?: number;
    }> = [];
  
    const excludedCandidates: Array<{ id: string; reason: string }> = [];
  
    const defaultCandidates: MealCandidate[] = [
      {
        id: "meal_001",
        name: "鶏のから揚げ",
        calories: 1850,
        cookingTime: 25,
        budget: 2800,
        allergyRisks: [],
        satisfactionScore: 65,
      },
      {
        id: "meal_002",
        name: "野菜炒め",
        calories: 1200,
        cookingTime: 15,
        budget: 1500,
        allergyRisks: [],
        satisfactionScore: 72,
      },
      {
        id: "meal_003",
        name: "サーモンのグリル",
        calories: 1600,
        cookingTime: 20,
        budget: 3200,
        allergyRisks: [],
        satisfactionScore: 85,
      },
    ];
  
    const mealsToProcess = candidateMenus.length > 0 ? candidateMenus : defaultCandidates;
  
    mealsToProcess.forEach((meal) => {
      const meetsCalorie = meal.calories <= calorieLimit;
      const meetsCookingTime = meal.cookingTime <= cookingTimeLimit;
      const meetsBudget = meal.budget <= budgetLimit;
  
      const hasAllergyConflict = meal.allergyRisks.some((risk) =>
        combinedAllergyExclusions.has(risk)
      );
  
      const meetsAllConstraints =
        meetsCalorie && meetsCookingTime && meetsBudget && !hasAllergyConflict;
  
      if (meetsAllConstraints) {
        const priorityLevel = priorityOrder[meal.id] ?? 0;
        rankedCandidates.push({
          id: meal.id,
          name: meal.name,
          calories: meal.calories,
          cookingTime: meal.cookingTime,
          budget: meal.budget,
          allergyRisks: meal.allergyRisks,
          satisfactionScore: meal.satisfactionScore,
          totalCalories: meal.calories,
          cookingTimeMinutes: meal.cookingTime,
          ingredients: [],
          priorityLevel,
        });
      } else {
        const reasons: string[] = [];
        if (!meetsCalorie) reasons.push("カロリー超過");
        if (!meetsCookingTime) reasons.push("調理時間超過");
        if (!meetsBudget) reasons.push("予算超過");
        if (hasAllergyConflict) reasons.push("アレルギー抵触");
        excludedCandidates.push({
          id: meal.id,
          reason: reasons.length > 0 ? reasons.join(", ") : "制約条件超過",
        });
      }
    });
  
    rankedCandidates.sort((a, b) => {
      const priorityDiff = (a.priorityLevel ?? 0) - (b.priorityLevel ?? 0);
      if (priorityDiff !== 0) return priorityDiff;
      return a.satisfactionScore - b.satisfactionScore;
    });
  
    const calculateConstraintScore = (
      value: number,
      limit: number,
      isInverse: boolean = false
    ): number => {
      if (limit === Infinity) return 100;
      const ratio = Math.min(value / limit, 1);
      return isInverse ? Math.round((1 - ratio) * 100) : Math.round(ratio * 100);
    };
  
    const calorieScore =
      rankedCandidates.length > 0
        ? Math.round(
            (rankedCandidates.reduce((sum, m) => sum + m.calories, 0) /
              rankedCandidates.length /
              calorieLimit) *
              100
          )
        : 100;
  
    const budgetScore =
      rankedCandidates.length > 0
        ? Math.round(
            (rankedCandidates.reduce((sum, m) => sum + m.budget, 0) /
              rankedCandidates.length /
              budgetLimit) *
              100
          )
        : 100;
  
    const cookingTimeScore =
      rankedCandidates.length > 0
        ? Math.round(
            (rankedCandidates.reduce((sum, m) => sum + m.cookingTime, 0) /
              rankedCandidates.length /
              cookingTimeLimit) *
              100
          )
        : 100;
  
    const allergyScore = 100;
  
    const constraintFulfillmentScores = {
      calorie: Math.min(calorieScore, 100),
      budget: Math.min(budgetScore, 100),
      cookingTime: Math.min(cookingTimeScore, 100),
      allergy: allergyScore,
    };
  
    const totalEvaluationScore = Math.round(
      (constraintFulfillmentScores.calorie +
        constraintFulfillmentScores.budget +
        constraintFulfillmentScores.cookingTime +
        constraintFulfillmentScores.allergy) /
        4
    );
  
    return {
      rankedCandidates: rankedCandidates as any,
      excludedCandidates,
      constraintFulfillmentScores,
      totalEvaluationScore,
      mealCandidates: rankedCandidates as any,
    };
  }
  return { generateMultiConstraintMeals };
})();
export const generateMultiConstraintMeals = __aivicBundle_13_generateMultiConstraintMeals.generateMultiConstraintMeals;
