    if (data.matchingUserCount === 0) {
      return {
        segmentId: data.segmentId,
        segmentConditions: segmentConditions,
        matchingUserCount: 0,
        differentiationEffectIndicators: null,
        mealGenerationSuccessRate: null,
        cookingTimeReductionDegree: null,
        userSatisfactionScore: null,
        status: 'empty_segment',
      };
    }
  
    return {
      segmentId: data.segmentId,
      segmentConditions: segmentConditions,
      matchingUserCount: data.matchingUserCount,
      differentiationEffectIndicators: data.differentiationEffectIndicators,
      mealGenerationSuccessRate: data.mealGenerationSuccessRate,
      cookingTimeReductionDegree: data.cookingTimeReductionDegree,
      userSatisfactionScore: data.userSatisfactionScore,
      status: data.status,
    };
