/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmImprovementQuantitatively exports=compareAlgorithmImprovementQuantitatively */
const __aivicBundle_20_compareAlgorithmImprovementQuantitatively = (() => {
  interface CompareAlgorithmImprovementQuantitativelyInput {
    beforeAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    afterAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    beforePeriodStartDate: Date;
    beforePeriodEndDate: Date;
    afterPeriodStartDate: Date;
    afterPeriodEndDate: Date;
    minimumDataRequirementDays: number;
  }
  
  interface CompareAlgorithmImprovementQuantitativelyResult {
    isAggregatable: boolean;
    errorMessage?: string;
    aggregatedComparison?: {
      beforeAvgSatisfaction: number;
      afterAvgSatisfaction: number;
      improvement: number;
    };
    dataCollectionDaysBefore: number;
    dataCollectionDaysAfter: number;
  }
  
   function compareAlgorithmImprovementQuantitatively(
    input: CompareAlgorithmImprovementQuantitativelyInput
  ): CompareAlgorithmImprovementQuantitativelyResult {
    const {
      beforeAlgorithmDataSet,
      afterAlgorithmDataSet,
      beforePeriodStartDate,
      beforePeriodEndDate,
      afterPeriodStartDate,
      afterPeriodEndDate,
      minimumDataRequirementDays
    } = input;
  
    const beforeStartTime = beforePeriodStartDate.getTime();
    const beforeEndTime = beforePeriodEndDate.getTime();
    const afterStartTime = afterPeriodStartDate.getTime();
    const afterEndTime = afterPeriodEndDate.getTime();
  
    const beforeDurationMs = beforeEndTime - beforeStartTime;
    const afterDurationMs = afterEndTime - afterStartTime;
  
    const beforeDays = Math.ceil(beforeDurationMs / (1000 * 60 * 60 * 24));
    const afterDays = Math.ceil(afterDurationMs / (1000 * 60 * 60 * 24));
  
    const isBeforeSufficient = beforeDays >= minimumDataRequirementDays;
    const isAfterSufficient = afterDays >= minimumDataRequirementDays;
  
    if (!isBeforeSufficient || !isAfterSufficient) {
      return {
        isAggregatable: false,
        errorMessage: `データ期間が不足しています。${minimumDataRequirementDays}日間以上のデータが必要です。1週間以上のデータが必要です。`,
        dataCollectionDaysBefore: beforeDays,
        dataCollectionDaysAfter: afterDays
      };
    }
  
    const beforeAvgSatisfaction =
      beforeAlgorithmDataSet.reduce((sum, item) => sum + item.satisfactionScore, 0) /
      beforeAlgorithmDataSet.length;
  
    const afterAvgSatisfaction =
      afterAlgorithmDataSet.reduce((sum, item) => sum + item.satisfactionScore, 0) /
      afterAlgorithmDataSet.length;
  
    const improvement = afterAvgSatisfaction - beforeAvgSatisfaction;
  
    return {
      isAggregatable: true,
      aggregatedComparison: {
        beforeAvgSatisfaction: Math.round(beforeAvgSatisfaction * 100) / 100,
        afterAvgSatisfaction: Math.round(afterAvgSatisfaction * 100) / 100,
        improvement: Math.round(improvement * 100) / 100
      },
      dataCollectionDaysBefore: beforeDays,
      dataCollectionDaysAfter: afterDays
    };
  }
  return { compareAlgorithmImprovementQuantitatively };
})();
export const compareAlgorithmImprovementQuantitatively = __aivicBundle_20_compareAlgorithmImprovementQuantitatively.compareAlgorithmImprovementQuantitatively;
