/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementComparison exports=calculateAlgorithmImprovementComparison */
const __aivicBundle_21_calculateAlgorithmImprovementComparison = (() => {
  function calculateAlgorithmImprovementComparison(
    testData: Array<{
      algorithmVersionId: string;
      mealPlanId: string;
      cookingTimeReductionMinutes: number;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
    }>
  ): {
    totalCookingTimeReductionMinutes: number;
    dataCount: number;
    averageCookingTimeReductionMinutes: number;
    averageSatisfactionScore: number;
    averageCompletionRate: number;
    averageRejectionRate: number;
    hasError: boolean;
  } {
    const validData = testData.filter(
      (item) =>
        item !== null &&
        item !== undefined &&
        typeof item.cookingTimeReductionMinutes === "number" &&
        !Number.isNaN(item.cookingTimeReductionMinutes) &&
        typeof item.satisfactionScore === "number" &&
        !Number.isNaN(item.satisfactionScore) &&
        typeof item.completionRate === "number" &&
        !Number.isNaN(item.completionRate) &&
        typeof item.rejectionRate === "number" &&
        !Number.isNaN(item.rejectionRate)
    );
  
    const dataCount = validData.length;
  
    if (dataCount === 0) {
      return {
        totalCookingTimeReductionMinutes: 0,
        dataCount: 0,
        averageCookingTimeReductionMinutes: 0,
        averageSatisfactionScore: 0,
        averageCompletionRate: 0,
        averageRejectionRate: 0,
        hasError: true,
      };
    }
  
    const totalCookingTimeReductionMinutes = validData.reduce(
      (sum, item) => sum + item.cookingTimeReductionMinutes,
      0
    );
  
    const totalSatisfactionScore = validData.reduce(
      (sum, item) => sum + item.satisfactionScore,
      0
    );
  
    const totalCompletionRate = validData.reduce(
      (sum, item) => sum + item.completionRate,
      0
    );
  
    const totalRejectionRate = validData.reduce(
      (sum, item) => sum + item.rejectionRate,
      0
    );
  
    const averageCookingTimeReductionMinutes =
      totalCookingTimeReductionMinutes / dataCount;
    const averageSatisfactionScore = totalSatisfactionScore / dataCount;
    const averageCompletionRate = totalCompletionRate / dataCount;
    const averageRejectionRate = totalRejectionRate / dataCount;
  
    return {
      totalCookingTimeReductionMinutes,
      dataCount,
      averageCookingTimeReductionMinutes,
      averageSatisfactionScore,
      averageCompletionRate,
      averageRejectionRate,
      hasError: false,
    };
  }
  return { calculateAlgorithmImprovementComparison };
})();
