/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealAfterAlgorithmImprovement exports=validateMealAfterAlgorithmImprovement */
const __aivicBundle_24_validateMealAfterAlgorithmImprovement = (() => {
  function validateMealAfterAlgorithmImprovement(
    mealData: {
      mealId: string;
      date: string;
      dishes: Array<{
        dishId: string;
        name: string;
        caloriesPer100g: number;
        servingSize: number;
        allergens: string[];
      }>;
    },
    constraints: {
      dailyCalorieLimit: number;
      allowedAllergens: string[];
      forbiddenAllergens: string[];
      proteinMinGrams: number;
      sodiumMaxMg: number;
    },
    familyMember: {
      memberId: string;
      age: number;
      gender: string;
    }
  ): {
    isAppropriate: boolean;
    violationReasons: string[];
    timestamp: string;
    mealId: string;
  } {
    const violationReasons: string[] = [];
  
    // Calculate total calories
    let totalCalories = 0;
    for (const dish of mealData.dishes) {
      totalCalories += (dish.caloriesPer100g / 100) * dish.servingSize;
    }
  
    // Check calorie limit
    if (totalCalories > constraints.dailyCalorieLimit) {
      violationReasons.push(
        `カロリー上限超過: ${Math.round(totalCalories)}kcal (上限: ${constraints.dailyCalorieLimit}kcal)`
      );
    }
  
    // Collect all allergens from dishes
    const mealAllergens = new Set<string>();
    for (const dish of mealData.dishes) {
      for (const allergen of dish.allergens) {
        mealAllergens.add(allergen);
      }
    }
  
    // Check forbidden allergens
    for (const allergen of mealAllergens) {
      if (constraints.forbiddenAllergens.includes(allergen)) {
        violationReasons.push(`指定アレルゲン含有: ${allergen}`);
      }
    }
  
    // Estimate sodium content (simplified: assume high-sodium dishes contribute)
    // For dishes with high salt content, estimate sodium
    let estimatedSodiumMg = 0;
    for (const dish of mealData.dishes) {
      // Estimate based on dish name and serving size
      if (
        dish.name.includes('漬物') ||
        dish.name.includes('塩') ||
        dish.name.includes('醤油')
      ) {
        estimatedSodiumMg += dish.servingSize * 8; // rough estimate: 8mg per gram for salty dishes
      } else {
        estimatedSodiumMg += dish.servingSize * 1; // base sodium estimate
      }
    }
  
    if (estimatedSodiumMg > constraints.sodiumMaxMg) {
      violationReasons.push(
        `塩分(ナトリウム)上限超過: ${Math.round(estimatedSodiumMg)}mg (上限: ${constraints.sodiumMaxMg}mg)`
      );
    }
  
    const isAppropriate = violationReasons.length === 0;
    const timestamp = new Date().toISOString();
  
    return {
      isAppropriate,
      violationReasons,
      timestamp,
      mealId: mealData.mealId
    };
  }
  return { validateMealAfterAlgorithmImprovement };
})();
