    // 全献立が有効かどうかを判定
    const allValid = mealValidations.every((v) => v.isValid);
  
    let message: string;
    if (!hasRestrictions) {
      message = "制限条件がないため全ての献立が有効です";
    } else if (allValid) {
      message = "全ての献立が制限条件を満たしています";
    } else {
      message = "一部の献立が制限条件を満たしていません";
    }
  
    return {
      statusCode: 200,
      isValid: allValid,
      mealValidations,
      message,
    };
