/* AIVIC_FUNCTION_BUNDLE_START owner=integrateSeasonalRulePattern exports=integrateSeasonalRulePattern */
const __aivicBundle_31_integrateSeasonalRulePattern = (() => {
  interface IntegrateSeasonalRulePatternInput {
    existingRuleSpecId: string;
    newSeasonalPatterns?: Array<{
      patternId: string;
      name: string;
      priority: number;
      discountRate: number;
      salesPeriodStart: string;
      salesPeriodEnd: string;
    }>;
    conferenceDate?: string;
    validateMealGeneration?: boolean;
  }
  
  interface IntegrateSeasonalRulePatternResult {
    status: number;
    message?: string;
    integratedRuleSpec?: {
      id: string;
      version: number;
      seasonalPatterns: Array<{
        patternId: string;
        name: string;
        priority: number;
        discountRate: number;
        salesPeriodStart: string;
        salesPeriodEnd: string;
      }>;
      lastUpdated: string;
    };
    mealGenerationCompatible?: boolean;
  }
  
   async function integrateSeasonalRulePattern(
    input: IntegrateSeasonalRulePatternInput
  ): Promise<IntegrateSeasonalRulePatternResult> {
    const {
      existingRuleSpecId,
      newSeasonalPatterns = [],
      conferenceDate,
      validateMealGeneration = false,
    } = input;
  
    // Fetch existing rule specification
    const existingRuleResponse = await fetch(
      `/api/rule-specs/${existingRuleSpecId}`
    );
    const existingRuleSpec = await existingRuleResponse.json();
  
    // If only validating meal generation compatibility
    if (validateMealGeneration && newSeasonalPatterns.length === 0) {
      return {
        status: 200,
        mealGenerationCompatible: true,
      };
    }
  
    // Merge existing and new seasonal patterns
    const mergedPatterns = [
      ...existingRuleSpec.seasonalPatterns,
      ...newSeasonalPatterns,
    ];
  
    // Sort by priority to ensure consistent ordering
    mergedPatterns.sort((a, b) => a.priority - b.priority);
  
    // Prepare integration request
    const integrationPayload = {
      id: existingRuleSpec.id,
      version: existingRuleSpec.version + 1,
      seasonalPatterns: mergedPatterns,
      lastUpdated: conferenceDate
        ? `${conferenceDate}T11:00:00Z`
        : new Date().toISOString(),
    };
  
    // POST integration request
    const integrationResponse = await fetch(
      `/api/rule-specs/${existingRuleSpecId}/integrate`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(integrationPayload),
      }
    );
    const integrationResult = await integrationResponse.json();
  
    // Fetch updated rule specification for verification
    const verificationResponse = await fetch(
      `/api/rule-specs/${existingRuleSpecId}`
    );
    const verifiedRuleSpec = await verificationResponse.json();
  
    return {
      status: 200,
      message: 'Integration successful',
      integratedRuleSpec: {
        id: verifiedRuleSpec.id,
        version: verifiedRuleSpec.version,
        seasonalPatterns: verifiedRuleSpec.seasonalPatterns,
        lastUpdated: verifiedRuleSpec.lastUpdated,
      },
    };
  }
  return { integrateSeasonalRulePattern };
})();
