const __aivicBundle_32_updateDiscountThresholdRule = (() => {
  interface UpdateDiscountThresholdRuleInput {
    ruleId: string;
    action?: string;
    seasonPattern?: string;
    discountRateThreshold?: number;
    salePeriodStart?: string;
    salePeriodEnd?: string;
    version?: number;
  }
  
  interface UpdateDiscountThresholdRuleOutput {
    ruleId: string;
    seasonPattern?: string;
    discountRateThreshold?: number;
    salePeriodStart?: string;
    salePeriodEnd?: string;
    lastUpdated: string;
    version: number;
    isPersisted: boolean;
  }
  
  const updateDiscountThresholdRuleStore: Record<string, UpdateDiscountThresholdRuleOutput> = {};
  
   function updateDiscountThresholdRule(
    input: UpdateDiscountThresholdRuleInput
  ): UpdateDiscountThresholdRuleOutput {
    const { ruleId, action, seasonPattern, discountRateThreshold, salePeriodStart, salePeriodEnd, version } = input;
  
    if (action === 'retrieve') {
      const stored = updateDiscountThresholdRuleStore[ruleId];
      if (stored) {
        return stored;
      }
      return {
        ruleId,
        lastUpdated: new Date().toISOString(),
        version: 0,
        isPersisted: false,
      };
    }
  
    const currentVersion = version ?? 0;
    const nextVersion = currentVersion + 1;
    const now = new Date().toISOString();
  
    const result: UpdateDiscountThresholdRuleOutput = {
      ruleId,
      seasonPattern,
      discountRateThreshold,
      salePeriodStart,
      salePeriodEnd,
      lastUpdated: now,
      version: nextVersion,
      isPersisted: true,
    };
  
    updateDiscountThresholdRuleStore[ruleId] = result;
  
    return result;
  }
  return { updateDiscountThresholdRule };
})();
