/* AIVIC_FUNCTION_BUNDLE_START owner=integrateSeasonalPatternAndDiscountRules exports=integrateSeasonalPatternAndDiscountRules */
const __aivicBundle_35_integrateSeasonalPatternAndDiscountRules = (() => {
  function integrateSeasonalPatternAndDiscountRules(
    ingredientInput: any,
    priorityRuleConfig: any
  ): any {
    const ingredientId = ingredientInput.ingredientId;
    const ingredientName = ingredientInput.ingredientName;
    const seasonalPattern = ingredientInput.seasonalPattern;
    const discountRate = ingredientInput.discountRate;
    const salePeriodStartDate = ingredientInput.salePeriodStartDate;
    const salePeriodEndDate = ingredientInput.salePeriodEndDate;
  
    const priorityOrder = priorityRuleConfig.priorityOrder || [];
    const seasonalPatternWeight = priorityRuleConfig.seasonalPatternWeight || 0;
    const discountRateWeight = priorityRuleConfig.discountRateWeight || 0;
    const salePeriodWeight = priorityRuleConfig.salePeriodWeight || 0;
  
    const isValidSalePeriod = salePeriodStartDate === salePeriodEndDate;
    const sameDatePeriodFlag = salePeriodStartDate === salePeriodEndDate;
  
    let priorityScore = 0;
    for (const factor of priorityOrder) {
      if (factor === "seasonalPattern") {
        priorityScore += seasonalPatternWeight * 100;
      } else if (factor === "discountRate") {
        priorityScore += discountRateWeight * 100;
      } else if (factor === "salePeriod") {
        priorityScore += salePeriodWeight * 100;
      }
    }
    priorityScore = Math.round(priorityScore);
  
    const canBeIncludedInMenu = isValidSalePeriod && priorityScore > 0;
    const generationLogStatus = canBeIncludedInMenu
      ? "processed_successfully"
      : "failed";
  
    return {
      ingredientId,
      ingredientName,
      seasonalPattern,
      discountRate,
      salePeriodStartDate,
      salePeriodEndDate,
      isValidSalePeriod,
      priorityScore,
      canBeIncludedInMenu,
      generationLogStatus,
      sameDatePeriodFlag,
    };
  }
  return { integrateSeasonalPatternAndDiscountRules };
})();
