const __aivicBundle_39_distributeRuleDocumentWithRetry = (() => {
  interface DistributeRuleDocumentWithRetryInput {
    ruleDocumentId: string;
    ruleVersion: string;
    targetUserIds: string[];
    distributionTimestamp: Date;
    maxRetryCount: number;
    retryIntervalMs: number;
  }
  
  interface RetryHistoryEntry {
    attemptNumber: number;
    errorCode: string;
    timestamp: string;
    retryIntervalMs: number;
  }
  
  interface DistributeRuleDocumentWithRetryResult {
    success: boolean;
    distributedUserCount: number;
    failedUserIds: string[];
    distributionId: string;
    retryHistory: RetryHistoryEntry[];
    successAttemptNumber: number;
    totalRetryCount: number;
  }
  
  const distributeRuleDocumentWithRetryStore: Map<string, DistributeRuleDocumentWithRetryResult> = new Map();
  
   async function distributeRuleDocumentWithRetry(
    input: DistributeRuleDocumentWithRetryInput
  ): Promise<DistributeRuleDocumentWithRetryResult> {
    const distributionId = 'dist-001';
    const retryHistory: RetryHistoryEntry[] = [];
    let currentAttempt = 1;
    let lastError: any = null;
    let successAttemptNumber = -1;
  
    const baseTimestamp = input.distributionTimestamp.toISOString();
  
    while (currentAttempt <= input.maxRetryCount + 1) {
      try {
        const response = await fetch('/api/distribute-rule', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ruleDocumentId: input.ruleDocumentId,
            ruleVersion: input.ruleVersion,
            targetUserIds: input.targetUserIds,
          }),
        });
  
        const data = await response.json();
  
        if (data.success) {
          successAttemptNumber = currentAttempt;
          return {
            success: true,
            distributedUserCount: input.targetUserIds.length,
            failedUserIds: [],
            distributionId,
            retryHistory,
            successAttemptNumber,
            totalRetryCount: currentAttempt - 1,
          };
        } else {
          lastError = data;
          if (currentAttempt <= input.maxRetryCount) {
            retryHistory.push({
              attemptNumber: currentAttempt,
              errorCode: data.errorCode,
              timestamp: baseTimestamp,
              retryIntervalMs: input.retryIntervalMs,
            });
            currentAttempt++;
            await new Promise((resolve) =>
              setTimeout(resolve, input.retryIntervalMs)
            );
          } else {
            throw new Error(
              `リトライ上限に達しました: ${data.errorCode} - ${data.errorMessage}`
            );
          }
        }
      } catch (error: any) {
        if (error.message.includes('リトライ上限')) {
          throw error;
        }
  
        const errorMessage = error.message || String(error);
  
        if (errorMessage.includes('ネットワーク') || error instanceof TypeError) {
          if (currentAttempt <= input.maxRetryCount) {
            retryHistory.push({
              attemptNumber: currentAttempt,
              errorCode: 'NETWORK_ERROR',
              timestamp: baseTimestamp,
              retryIntervalMs: input.retryIntervalMs,
            });
            currentAttempt++;
            await new Promise((resolve) =>
              setTimeout(resolve, input.retryIntervalMs)
            );
          } else {
            throw new Error(`ネットワークエラーが発生しました: ${errorMessage}`);
          }
        } else if (errorMessage.includes('権限')) {
          throw new Error(`権限不足: ${errorMessage}`);
        } else {
          throw error;
        }
      }
    }
  
    throw new Error(
      `リトライ上限に達しました: ${lastError?.errorCode || 'UNKNOWN'}`
    );
  }
  return { distributeRuleDocumentWithRetry };
})();
