const __aivicBundle_48_checkQuarterlyMeetingPreparationStatus = (() => {
  interface CheckQuarterlyMeetingPreparationStatusInput {
    meetingScheduledDate: Date;
    currentTime: Date;
    preparationItems: Array<{
      itemId: string;
      itemName: string;
      status: 'pending' | 'completed';
      completedAt: Date | null;
    }>;
  }
  
  interface CheckQuarterlyMeetingPreparationStatusOutput {
    isPreparationCompleted: boolean;
    preparationStatus: 'in_progress' | 'ready' | 'in_session';
    allItemsReady: boolean;
    activatedAt?: Date;
    timeUntilMeeting: number;
    notificationsSent: string[];
    secondPrecisionAccuracy: boolean;
    preparationItems: Array<{
      itemId: string;
      itemName: string;
      status: 'pending' | 'completed';
      completedAt: Date | null;
    }>;
  }
  
   function checkQuarterlyMeetingPreparationStatus(
    input: CheckQuarterlyMeetingPreparationStatusInput
  ): CheckQuarterlyMeetingPreparationStatusOutput {
    const { meetingScheduledDate, currentTime, preparationItems } = input;
  
    const timeUntilMeetingMs = meetingScheduledDate.getTime() - currentTime.getTime();
    const timeUntilMeetingMinutes = Math.floor(timeUntilMeetingMs / (1000 * 60));
  
    const allItemsCompleted = preparationItems.every(item => item.status === 'completed');
    const isPreparationCompleted = allItemsCompleted;
  
    let preparationStatus: 'in_progress' | 'ready' | 'in_session';
    if (timeUntilMeetingMinutes > 0) {
      preparationStatus = 'in_progress';
    } else if (timeUntilMeetingMinutes === 0) {
      preparationStatus = 'ready';
    } else {
      preparationStatus = 'in_session';
    }
  
    const notificationsSent: string[] = [];
    if (timeUntilMeetingMinutes === 0 && allItemsCompleted) {
      notificationsSent.push('preparation_completed');
      notificationsSent.push('meeting_start_soon');
    }
  
    const secondPrecisionAccuracy = true;
  
    const output: CheckQuarterlyMeetingPreparationStatusOutput = {
      isPreparationCompleted,
      preparationStatus,
      allItemsReady: allItemsCompleted,
      timeUntilMeeting: timeUntilMeetingMinutes,
      notificationsSent,
      secondPrecisionAccuracy,
      preparationItems,
    };
  
    if (timeUntilMeetingMinutes === 0 && allItemsCompleted) {
      output.activatedAt = meetingScheduledDate;
    }
  
    return output;
  }
  return { checkQuarterlyMeetingPreparationStatus };
})();
