/* AIVIC_FUNCTION_BUNDLE_START owner=assignProxyParticipant exports=assignProxyParticipant */
const __aivicBundle_51_assignProxyParticipant = (() => {
  function assignProxyParticipant(input: {
    meeting_id: string;
    participants: Array<{
      participant_id: string;
      name: string;
      status: string;
      role: string;
    }>;
    proxy_candidate_id: string;
  }): {
    assignmentSuccess: boolean;
    proxyAssignedAt: string;
    originalParticipant: string;
    assignedProxy: string;
    validationErrors: string[];
  } {
    const validationErrors: string[] = [];
  
    const absentParticipants = input.participants.filter(
      (p) => p.status === 'absent'
    );
  
    if (absentParticipants.length === input.participants.length) {
      throw new Error('全参加者が欠席しているため、代理参加者を割り当てることができません');
    }
  
    if (absentParticipants.length === 0) {
      validationErrors.push('欠席している参加者がいません');
      return {
        assignmentSuccess: false,
        proxyAssignedAt: '',
        originalParticipant: '',
        assignedProxy: '',
        validationErrors,
      };
    }
  
    const absentParticipant = absentParticipants[0];
  
    if (absentParticipant.participant_id === input.proxy_candidate_id) {
      validationErrors.push('代理人は本人と異なる必要があります');
      return {
        assignmentSuccess: false,
        proxyAssignedAt: '',
        originalParticipant: absentParticipant.participant_id,
        assignedProxy: '',
        validationErrors,
      };
    }
  
    const proxyExists = input.participants.some(
      (p) => p.participant_id === input.proxy_candidate_id
    );
  
    if (!proxyExists) {
      validationErrors.push('指定された代理人が参加者リストに存在しません');
      return {
        assignmentSuccess: false,
        proxyAssignedAt: '',
        originalParticipant: absentParticipant.participant_id,
        assignedProxy: input.proxy_candidate_id,
        validationErrors,
      };
    }
  
    const proxyParticipant = input.participants.find(
      (p) => p.participant_id === input.proxy_candidate_id
    );
  
    if (proxyParticipant && proxyParticipant.status === 'absent') {
      validationErrors.push('代理人も欠席しているため割り当てできません');
      return {
        assignmentSuccess: false,
        proxyAssignedAt: '',
        originalParticipant: absentParticipant.participant_id,
        assignedProxy: input.proxy_candidate_id,
        validationErrors,
      };
    }
  
    const now = new Date().toISOString();
  
    return {
      assignmentSuccess: true,
      proxyAssignedAt: now,
      originalParticipant: absentParticipant.participant_id,
      assignedProxy: input.proxy_candidate_id,
      validationErrors: [],
    };
  }
  return { assignProxyParticipant };
})();
export const assignProxyParticipant = __aivicBundle_51_assignProxyParticipant.assignProxyParticipant;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignProxyParticipant */

