const __aivicBundle_52_validateMeetingAttendance = (() => {
  function validateMeetingAttendance(input: {
    meetingId: string;
    scheduledTime: Date;
    checkTime: Date;
    attendees: Array<{
      memberId: string;
      memberName: string;
      role: string;
      isMandatory: boolean;
      attendanceStatus: string;
      alternativeMemberId: string | null;
      alternativeMemberName: string | null;
    }>;
  }): {
    hasWarning: boolean;
    warningCount: number;
    warnings: Array<{
      type: string;
      memberId: string;
      memberName: string;
      severity: string;
      message: string;
    }>;
    shouldNotifyBefore: boolean;
    notificationDeliveryTime: number;
    meetingCanProceeded: boolean;
  } {
    const warnings: Array<{
      type: string;
      memberId: string;
      memberName: string;
      severity: string;
      message: string;
    }> = [];
  
    for (const attendee of input.attendees) {
      if (
        attendee.isMandatory &&
        attendee.attendanceStatus === 'absent' &&
        !attendee.alternativeMemberId
      ) {
        warnings.push({
          type: 'mandatoryAbsentNoAlternative',
          memberId: attendee.memberId,
          memberName: attendee.memberName,
          severity: 'critical',
          message: `${attendee.memberName}が欠席で代理参加者がいません`,
        });
      }
    }
  
    const hasWarning = warnings.length > 0;
    const shouldNotifyBefore = hasWarning && input.checkTime < input.scheduledTime;
    const notificationDeliveryTime = input.checkTime.getTime();
    const meetingCanProceeded = !hasWarning;
  
    return {
      hasWarning,
      warningCount: warnings.length,
      warnings,
      shouldNotifyBefore,
      notificationDeliveryTime,
      meetingCanProceeded,
    };
  }
  return { validateMeetingAttendance };
})();
