const __aivicBundle_55_confirmMeetingAttendance = (() => {
  function confirmMeetingAttendance(
    meetingData: any,
    confirmationAction: any
  ): any {
    const updatedMeeting = {
      ...meetingData,
      attendees: meetingData.attendees.map((attendee: any) => {
        if (attendee.attendeeId === confirmationAction.attendeeId) {
          return {
            ...attendee,
            status: 'confirmed',
            confirmedAt: confirmationAction.confirmedAt,
          };
        }
        return attendee;
      }),
    };
  
    const allConfirmed = updatedMeeting.attendees.every(
      (attendee: any) => attendee.status === 'confirmed'
    );
  
    if (allConfirmed) {
      updatedMeeting.meetingStatus = 'confirmed';
      updatedMeeting.meetingConfirmedAt = confirmationAction.confirmedAt;
      updatedMeeting.isConfirmed = true;
    } else {
      updatedMeeting.meetingStatus = 'pending_confirmation';
    }
  
    return updatedMeeting;
  }
  return { confirmMeetingAttendance };
})();
