const __aivicBundle_57_validateMeetingParticipants = (() => {
  function validateMeetingParticipants(config: {
    meeting_id: string;
    scheduled_participants: Array<{
      participant_id: string;
      participant_name: string;
      attendance_status: string;
      substitute_id: string | null;
    }>;
    minimum_required_participants: number;
  }): {
    actual_attendees_count: number;
    effective_attendees_count: number;
    meeting_status: string;
    is_valid: boolean;
    absent_without_substitute: Array<{
      participant_id: string;
      participant_name: string;
    }>;
  } {
    const { scheduled_participants, minimum_required_participants } = config;
  
    // 実際の出席者数（attendance_status が "attended" の人数）
    const actual_attendees_count = scheduled_participants.filter(
      (p) => p.attendance_status === "attended"
    ).length;
  
    // 代理者がいる不在者を有効出席者として計算
    const substituted_count = scheduled_participants.filter(
      (p) => p.attendance_status === "absent" && p.substitute_id !== null
    ).length;
  
    // 有効出席者数 = 実出席者 + 代理者がいる不在者
    const effective_attendees_count = actual_attendees_count + substituted_count;
  
    // 代理者がいない不在者を抽出
    const absent_without_substitute = scheduled_participants
      .filter(
        (p) => p.attendance_status === "absent" && p.substitute_id === null
      )
      .map((p) => ({
        participant_id: p.participant_id,
        participant_name: p.participant_name,
      }));
  
    // 有効出席者数が最小必要人数以上なら開催可能
    const can_proceed = effective_attendees_count >= minimum_required_participants;
  
    return {
      actual_attendees_count,
      effective_attendees_count,
      meeting_status: can_proceed ? "can_proceed" : "cannot_proceed",
      is_valid: can_proceed,
      absent_without_substitute,
    };
  }
  return { validateMeetingParticipants };
})();
export const validateMeetingParticipants = __aivicBundle_57_validateMeetingParticipants.validateMeetingParticipants;
